package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

type User struct {
	Name string `form:"name" json:"name" binding:"required"`
	Age  int    `form:"age" json:"age"`
}

func main() {
	r := gin.New()
	// 按 Content-Type 自动挑绑定器
	r.POST("/any", func(c *gin.Context) {
		var u User
		if err := c.ShouldBind(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})
	// 只收 JSON 时直接指定绑定器，不看 Content-Type
	r.POST("/json", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	post := func(path, body, contentType string) {
		req := httptest.NewRequest(http.MethodPost, path, strings.NewReader(body))
		req.Header.Set("Content-Type", contentType)
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Println(path, w.Code, w.Body.String())
	}
	post("/any", "name=tom&age=18", "application/x-www-form-urlencoded")
	post("/any", `{"name":"张三","age":20}`, "application/json")
	post("/json", `{"name":"李四"}`, "text/plain")
}

