import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

type User struct {
	Name string `json:"name" binding:"required"`
}

func main() {
	r := gin.New()
	// BindJSON 失败时自己写 400 并中止，错误记在 c.Errors
	r.POST("/bind", func(c *gin.Context) {
		var u User
		if err := c.BindJSON(&u); err != nil {
			fmt.Println("bind 错误:", c.Errors.Last().Err)
			return
		}
		c.JSON(http.StatusOK, u)
	})
	// ShouldBindJSON 失败只返回 error，响应自己写
	r.POST("/should", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	body := `{"name": ""}`
	for _, path := range []string{"/bind", "/should"} {
		req := httptest.NewRequest(http.MethodPost, path, strings.NewReader(body))
		req.Header.Set("Content-Type", "application/json")
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Printf("%s: %d %q\n", path, w.Code, w.Body.String())
	}
}

