func main() {
	r := gin.New()
	r.POST("/echo", func(c *gin.Context) {
		// 不想定义结构体就直接绑到 map，map 要先初始化成空的
		m := map[string]string{}
		if err := c.ShouldBind(&m); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, m)
	})
	r.POST("/echo-json", func(c *gin.Context) {
		// JSON 绑到 map[string]any，不用先初始化
		var m map[string]any
		if err := c.ShouldBindJSON(&m); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, m)
	})

	req := httptest.NewRequest(http.MethodPost, "/echo", strings.NewReader("name=tom&age=18"))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println("/echo:", w.Code, w.Body.String())

	req2 := httptest.NewRequest(http.MethodPost, "/echo-json", strings.NewReader(`{"name":"tom","age":18}`))
	req2.Header.Set("Content-Type", "application/json")
	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, req2)
	fmt.Println("/echo-json:", w2.Code, w2.Body.String())
