type User struct {
	Name string `json:"name"`
}

func main() {
	r := gin.New()
	r.POST("/users", func(c *gin.Context) {
		var u User
		// 第一次读 body，同时把原始字节缓存进 c.Keys
		if err := c.ShouldBindBodyWith(&u, binding.JSON); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		// 第二次再绑同一个 body 还能成功
		var again User
		if err := c.ShouldBindBodyWith(&again, binding.JSON); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, gin.H{"first": u.Name, "second": again.Name})
	})

	req := httptest.NewRequest(http.MethodPost, "/users", strings.NewReader(`{"name":"张三"}`))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Code, w.Body.String())
}

